import{z as s,x as A,o as e,c as p,q as o,j as l,D as t,d as i,s as B,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"tick size pilot 实证","description":"","frontmatter":{"title":"tick size pilot 实证","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/tick-size-pilot.md","filePath":"quant/tick-size-pilot.md","lastUpdated":1791413859000}'),c={name:"quant/tick-size-pilot.md"};function d(k,a,u,m,h,f){const r=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="tick-size-pilot-实证" tabindex="-1">tick size pilot 实证 <a class="header-anchor" href="#tick-size-pilot-实证" aria-label="Permalink to &quot;tick size pilot 实证&quot;">​</a></h1><div class="epigraph"><p>把小盘股的最小报价单位从一分钱抬到五分钱，是一次罕见的栅格实验：报价价差几乎必定变宽，真正要测量的是展示深度、有效成本与发现，有没有换来可成交的厚度。</p><footer>—— SEC Tick Size Pilot Program（2016–2018）；Albuquerque, Song and Yao, Journal of Financial Economics, 2020；对照 Harris, Review of Financial Studies, 1991</footer></div><p><a href="/quant/reg-nms-order-protection">订单保护</a>里的 Rule 612 已经禁止一美元以上股票的亚分<em>报价</em>。缺口是反方向的政策实验：对一批小盘股，强制把报价 tick 从 \\(\\$0.01\\) 放到 \\(\\$0.05\\)。<a href="/quant/tick-size-regime">最小变动价位</a> 写过相对 tick 的机制；本课只写 Pilot 的识别与读数，不把 Harris 的聚类论文再讲一遍，也不外推成「所有股票都应加粗」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小数化之后，许多小盘股长期钉在一个 tick，队列价值高，公开做市的名义价差收入却薄。Pilot 的政策叙事是：更粗的栅格让做市商愿意展示更多深度，便于机构积累小盘仓位。理论预测并不单向。Harris 早已说明粗栅格抬高价差下限、加剧时间优先竞赛；细栅格摊薄每档深度、鼓励一 tick 插队。有效价差还受中点成交、暗池与<a href="/quant/retail-wholesaler">批发商内化</a> 影响——公开 \\(n=1\\) 被钉住时，经济步长可以仍在包络内。问题是：报价价差上升多少、有效价差是否同幅上升、深度增加是否可重复成交，以及「trade-at」一类附加规则有没有把量从暗处赶回明簿。</p><p><span class="marginnote">数字实例：一只 \\(\\$3\\) 的小盘股，1 分 tick 的最小价差约 33bp；改成 5 分后最小价差跳到约 1.7%，是原来的五倍。对 \\(\\$50\\) 的大盘股，同样 1 分只有约 2bp——所以「加粗 tick」本质是小盘股政策，栅格宽度必须相对价格看，不能只看绝对分值。</span></p><h3 id="分组不是单一处理" tabindex="-1">分组不是单一处理 <a class="header-anchor" href="#分组不是单一处理" aria-label="Permalink to &quot;分组不是单一处理&quot;">​</a></h3><p>Pilot 把合格小盘股随机（近似）分到对照与处理组。处理组里还拆过：仅加宽 tick、加宽加 trade-at（限制以劣于保护报价的价格在场外成交）等。把所有处理组捏成一个虚拟变量，会把「栅格」与「强制明簿优先」混成一剂。读任何一张表，先问它估计的是哪一个处理臂。</p><p><span class="marginnote">Pilot 同时发生在 maker-taker、碎片化与 HFT 做市的均衡里。识别靠组间差，不靠与 1990 年代小数化前后的长差对比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件研究的最小集合：报价价差、有效价差、实现价差、近端深度（股数与金额）、成交量、明暗份额、以及短窗价格冲击。必须分约束状态：处理前已经 \\(n=1\\) 的名字，加宽几乎是把下限从 1 分抬到 5 分；处理前价差常大于 5 分的名字，栅格可能仍不绑紧。Albuquerque、Song 与 Yao（2020）把流动性冲击的价格效应从单纯「价差变宽」里拆出来：若深度真正改善，资产价格应反映更低的预期交易成本；若只是制度租金，价格应下跌。Griffith 与 Roseman 等报告市场质量指标对处理臂的异质性。不要只用报价价差当成功标准。</p><p>跨所：相对 tick 变粗后，中点与亚 tick 通道更有吸引力，暗份额与零售改善可能上升，公开深度的「看起来变厚」要扣掉不可成交的堆量。这与 <a href="/quant/price-time-pro-rata">pro-rata 假厚</a> 同一读法。</p><p><span class="marginnote">术语翻译：「trade-at」是试点里的一个附加处理臂——要求场外成交价不得劣于公开保护报价，试图关掉「公开挂单、暗里成交」的搭便车道。它与单纯加宽 tick 是两个不同的处理，混在一起估计会把制度效应算到栅格头上。</span></p>',13)),(e(),l(n,null,{default:t(()=>[B(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20Tick%5B%22tick%20%E4%BB%8E%201%20%E5%88%86%E5%88%B0%205%20%E5%88%86%22%5D%20--%3E%20Spread%5B%22%E6%8A%A5%E4%BB%B7%E4%BB%B7%E5%B7%AE%E4%B8%8B%E9%99%90%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Tick%20--%3E%20Queue%5B%22%E6%97%B6%E9%97%B4%E4%BC%98%E5%85%88%E6%9B%B4%E5%80%BC%E9%92%B1%22%5D%0A%20%20Tick%20--%3E%20Dark%5B%22%E4%B8%AD%E7%82%B9%20%2F%20%E5%86%85%E5%8C%96%E7%9B%B8%E5%AF%B9%E6%9B%B4%E6%9C%89%E5%90%B8%E5%BC%95%E5%8A%9B%22%5D%0A%20%20TradeAt%5B%22trade-at%20%E8%87%82%22%5D%20--%3E%20Lit%5B%22%E9%87%8F%E8%A2%AB%E8%B5%B6%E5%90%91%E4%BF%9D%E6%8A%A4%E6%8A%A5%E4%BB%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"加粗 tick 是把 Stoll 处理成分的下限抬高：即使逆向选择很小，买卖也不能报到 1 分。展示深度可以增加，因为同一价位上的协调焦点更粗，排队租金上升，做市商更愿意占位。有效成本是否下降，取决于这笔深度在信息到达时撤不撤、以及有多少成交改走中点。trade-at 试图切断「公开报价、暗处成交」的搭便车，把保护规则从「不能更差」推进到「不能绕开展示」。它改变的是暗池与批发商的相对吸引力，不只是格子宽度。",-1)),(e(),l(n,null,{default:t(()=>[B(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%A4%84%E7%90%86%E7%BB%84%E4%B8%8E%E5%AF%B9%E7%85%A7%E7%BB%84%E4%B9%8B%E5%B7%AE%22%5D%20--%3E%20S%7B%22%E6%8A%A5%E4%BB%B7%E4%BB%B7%E5%B7%AE%E5%8F%98%E5%AE%BD%E5%A4%9A%E5%B0%91%22%7D%0A%20%20S%20--%3E%20D%7B%22%E5%B1%95%E7%A4%BA%E6%B7%B1%E5%BA%A6%E6%98%AF%E5%90%A6%E5%90%8C%E5%8D%87%E4%B8%94%E5%8F%AF%E6%88%90%E4%BA%A4%22%7D%0A%20%20D%20--%20%22%E5%8F%AA%E5%A0%86%E4%BB%B7%E4%B8%8D%E5%A0%86%E9%87%8F%22%20--%3E%20RENT%5B%22%E5%88%B6%E5%BA%A6%E7%A7%9F%E9%87%91%3A%20%E6%B7%B1%E5%BA%A6%E6%98%AF%E6%91%86%E8%AE%BE%22%5D%0A%20%20D%20--%20%22%E7%9C%9F%E5%8F%98%E5%8E%9A%22%20--%3E%20P%7B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%E5%A6%82%E4%BD%95%E5%8F%8D%E5%BA%94%22%7D%0A%20%20P%20--%20%22%E4%B8%8A%E5%8D%87%22%20--%3E%20GOOD%5B%22%E9%A2%84%E6%9C%9F%E4%BA%A4%E6%98%93%E6%88%90%E6%9C%AC%E4%B8%8B%E9%99%8D%3A%20%E7%9C%9F%E6%94%B9%E5%96%84%22%5D%0A%20%20P%20--%20%22%E4%B8%8B%E8%B7%8C%22%20--%3E%20RENT%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>对放置：Roşu 式近端挂单在 5 分格子上选择更少，队头竞赛更像期货粗 tick。把股票 FIFO 切片算法原样搬到 Pilot 期小盘股，会低估占位价值、高估一 tick 改善的机会。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>样本是当时规则下的美国小盘股，2016–2018 年，不能外推到大盘、不能外推到加密细 tick、也不能当成 A 股分档 tick 的估计。Pilot 结束后栅格回到 1 分，长期均衡未必等于试点窗。SEC 工作人员分析与学术论文的处理定义、股票筛选并不完全相同，复制必须对齐名单。下一课换一把制度刀：熔断停止连续协议本身，而不是改格子。</p><p><span class="marginnote">回测若在 Pilot 名单上用统一 1 分假设生成报价，会凭空制造当时不合法的价差。</span></p><p>栅格约束的是连续交易里的合法价格。下一课的熔断约束的是连续交易能否发生：阈值、暂停时长与重开协议，比 tick 更硬地切开螺旋中的订单流。</p><p>Harris 的比较静态在试点里被估计，不因某一个处理臂的符号而作废；失败的是把「加粗」当成单一质量开关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pilot 是栅格实验，不是「流动性好坏」的单一开关；先分处理臂，再分是否 tick 约束。</li><li>报价价差上升是设计直接量；有效价差、可成交深度与资产价格效应才是质量。</li><li>trade-at 改变明暗分流，与单纯加宽 tick 不是同一处理。</li><li>出处：SEC Tick Size Pilot 计划与工作人员分析；Albuquerque, Song and Yao, <em>JFE</em>, 2020；Griffith and Roseman, <em>Journal of Corporate Finance</em>, 2019；机制见 Harris, <em>RFS</em>, 1991。</li></ul>',8))])}const q=s(c,[["render",d]]);export{P as __pageData,q as default};
